24: function showToast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
25: function setQuest(n){state.quest=n%quests.length;state.done.clear();renderQuest();showToast('A fresh little quest is ready ✦')}
26: function complete(key){if(state.done.has(key))return;state.done.add(key);renderQuest();const task=quests[state.quest].tasks.find(t=>t[0]===key);showToast(task?`Quest step complete: ${task[1]} ✓`:'Nice one — progress saved!');if(state.done.size===quests[state.quest].tasks.length){showToast('Duo quest complete! You make a great team ✨');celebrate()}}
27: function renderQuest(){const q=quests[state.quest];document.querySelector('#questTitle').textContent=q.title;document.querySelector('#questCount').textContent=`${state.done.size} / ${q.tasks.length}`;document.querySelector('#progressFill').style.width=`${state.done.size/q.tasks.length*100}%`;document.querySelector('#questSteps').innerHTML=q.tasks.map(([key,label,app])=>`<div class="quest-step ${state.done.has(key)?'done':''}"><b>${state.done.has(key)?'✓':'○'}</b>${label}</div>`).join('')}
28: function celebrate(){const layer=document.querySelector('#confetti');const colors=['#ff806d','#a894ff','#8ce4bb','#f8c46b','#fff'];for(let i=0;i<55;i++){const bit=document.createElement('i');bit.className='confetti-piece';bit.style.left=Math.random()*100+'%';bit.style.background=colors[i%colors.length];bit.style.animationDelay=Math.random()*.55+'s';bit.style.transform=`rotate(${Math.random()*180}deg)`;layer.append(bit);setTimeout(()=>bit.remove(),2300)}}
