31: function renderHomes(){[1,2].forEach(p=>{const el=document.querySelector(`#content${p}`);if(!state.open[p])el.innerHTML=home(p);else el.innerHTML=renderApp(state.open[p],p);el.querySelectorAll('[data-open]').forEach(btn=>btn.addEventListener('click',()=>openApp(p,btn.dataset.open)));el.querySelectorAll('[data-action]').forEach(btn=>btn.addEventListener('click',()=>action(p,btn.dataset.action,btn)))});updateClock()}
