37: function messageApp(){return shell(1,'Messages',`<div class="app-kicker">FRIENDS</div><h2 class="app-title">Good morning ☀️</h2><div class="chat-list">${state.messages.map(m=>`<div class="message-row"><div class="avatar">${m.from==='You'?'Y':'M'}</div><div class="chat-copy"><b>${m.from}</b><div>${escapeHtml(m.text)}</div></div><small>${m.time}</small></div>`).join('')}</div><div class="soft-card"><div class="app-kicker">QUICK REPLIES</div><div class="quick-replies"><button class="pill" data-action="reply-coffee">Absolutely! ☕</button><button class="pill" data-action="reply-walk">Let's do it 🚶</button><button class="pill" data-action="reply-later">Maybe later 💛</button></div></div><div class="compose"><input class="app-input" id="messageInput" placeholder="iMessage" maxlength="120"><button class="send-button" data-action="send-message" aria-label="Send">↑</button></div>`)}
38: function notesApp(){return shell(1,'Notes',`<div class="app-kicker">QUICK NOTE</div><h2 class="app-title">A thought for later.</h2><div class="soft-card"><input id="noteTitle" class="app-input" placeholder="Title your note" maxlength="35" value="${escapeAttr(state.noteDraftTitle||'')}"/><textarea id="noteText" class="app-textarea" placeholder="Start typing...">${escapeHtml(state.noteDraft||'')}</textarea><div class="note-actions"><span class="app-subtitle">${state.notes.length} saved note${state.notes.length===1?'':'s'}</span><button class="primary-action coral-action" data-action="save-note">Save note</button></div></div><div class="saved-notes">${state.notes.slice().reverse().map(n=>`<div class="soft-card saved-note"><b>📝 ${escapeHtml(n.title||'Untitled')}</b><p>${escapeHtml(n.text)}</p></div>`).join('')}</div>`)}
39: function safariApp(){return shell(2,'Safari',`<div class="app-kicker">THE WEB IS YOURS</div><h2 class="app-title">Where to today?</h2><form class="browser-form" id="browserForm"><span>⌕</span><input id="browserInput" class="app-input" placeholder="Search or enter a website" autocomplete="url"><button type="submit" aria-label="Go">↗</button></form><div class="app-kicker" style="margin-top:19px">QUICK EXPLORE</div><div class="site-grid"><button data-site="https://www.wikipedia.org"><b class="site-icon wiki">W</b><span>Wikipedia</span></button><button data-site="https://www.nasa.gov"><b class="site-icon nasa">NASA</b><span>NASA</span></button><button data-site="https://www.nationalgeographic.com"><b class="site-icon natgeo">N</b><span>Nat Geo</span></button><button data-site="https://www.metmuseum.org"><b class="site-icon met">M</b><span>The Met</span></button></div><div class="soft-card browser-hint"><b>Go anywhere.</b><p>Search the web, or enter a full website address. Links open in a new tab so your duo stays right here.</p><span class="pill">Real websites ↗</span></div><div id="searchResults"></div>`)}
40: function musicApp(){const [title,artist]=songs[state.song];return shell(2,'Music',`<div class="app-kicker">MADE FOR THIS MOMENT</div><h2 class="app-title">A little soundtrack.</h2><div class="album-art"><div class="album-orb"></div><span>DUO<br>RADIO</span></div><div class="track-info"><b>${title}</b><span>${artist}</span></div><div class="music-progress"><i class="${state.playing?'is-playing':''}"></i></div><div class="music-controls"><button data-action="prev-song" aria-label="Previous">↶</button><button class="play-button" data-action="toggle-play" aria-label="Play">${state.playing?'Ⅱ':'▶'}</button><button data-action="next-song" aria-label="Next">↷</button></div><div class="soft-card music-queue"><span>UP NEXT</span><b>${songs[(state.song+1)%songs.length][0]}</b><small>DUO MIX · ${songs.length} SONGS</small></div>`)}
