42: function mapsApp(){return shell(1,'Maps',`<div class="app-kicker">AROUND YOU</div><h2 class="app-title">Pick a destination.</h2><div class="map-art"><div class="map-road road-one"></div><div class="map-road road-two"></div><div class="map-road road-three"></div><span class="map-pin">⌖</span><span class="map-label">YOU ARE HERE</span><span class="map-park">GREEN PARK</span></div><div class="place-list">${places.map((p,i)=>`<button class="place-row ${state.route===i?'selected':''}" data-action="place-${i}"><span class="place-emoji">${p[2]}</span><span><b>${p[0]}</b><small>${p[1]}</small></span><i>›</i></button>`).join('')}</div>${state.route===null?'':`<div class="route-card"><b>Route ready · ${places[state.route][0]}</b><p>Head east on Willow Lane. You'll be there in a few minutes.</p><button class="primary-action green-action" data-action="start-route">${state.routeStarted?'End route':'Start walking'}</button></div>`}`)}
43: function cameraApp(){return shell(2,'Camera',`<div class="camera-app"><div class="camera-view"><div class="camera-sun"></div><div class="camera-hill hill-back"></div><div class="camera-hill hill-front"></div><div class="camera-caption">${state.photos.length?`Duo memory #${state.photos.length}`:'A moment worth keeping'}</div></div><div class="camera-tip">Tap the shutter to keep this little moment.</div><button class="shutter" data-action="shutter" aria-label="Take photo"><i></i></button><div class="camera-mini">${state.photos.length?`<span>▧ ${state.photos.length} saved</span><button data-action="open-photos">View photos ↗</button>`:'A sunny day, saved forever.'}</div></div>`)}
44: function weatherApp(){const value=state.weatherF?'73°':'23°';return shell(1,'Weather',`<div class="weather-hero"><div class="app-kicker">YOUR NEIGHBORHOOD</div><h2 class="weather-temp">${value}</h2><div class="weather-desc">Mostly sunny <span>☀️</span></div><div class="weather-place">Brooklyn, NY</div><div class="weather-high">H: ${state.weatherF?'77°':'25°'} &nbsp; L: ${state.weatherF?'64°':'18°'}</div></div><div class="soft-card forecast"><div class="app-kicker">THE NEXT FEW HOURS</div><div class="forecast-row">${[['NOW','☀️','23°'],['11 AM','🌤️','24°'],['12 PM','☀️','25°'],['1 PM','☀️','24°']].map(x=>`<span><small>${x[0]}</small><b>${x[1]}</b><i>${state.weatherF?Math.round((parseInt(x[2])-32)*9/5+32)+'°':x[2]}</i></span>`).join('')}</div></div><button class="primary-action" data-action="toggle-temp">Show in °${state.weatherF?'C':'F'}</button> <button class="pill" data-action="refresh-weather">↻ Refresh</button>`)}
45: function calendarApp(){return shell(1,'Calendar',`<div class="app-kicker">FRIDAY · NOVEMBER 7</div><h2 class="app-title">Good things ahead.</h2><div class="calendar-date"><span>FRI</span><b>07</b><small>NOVEMBER</small></div><div class="soft-card event-card"><div class="event-time">11:30 <small>AM</small></div><div class="event-divider"></div><div><b>Brunch & a catch-up</b><p>Little Fern Café · 2 guests</p><button class="${state.calendarJoined?'pill':'primary-action coral-action'}" data-action="rsvp">${state.calendarJoined?'✓ You’re going':'RSVP · Going?'}</button></div></div><div class="soft-card event-card"><div class="event-time">4:00 <small>PM</small></div><div class="event-divider purple"></div><div><b>Golden hour walk</b><p>Riverside Garden · Maybe</p><span class="pill">On your calendar</span></div></div>`)}
46: function photosApp(){return shell(2,'Photos',`<div class="app-kicker">YOUR LITTLE MOMENTS</div><h2 class="app-title">All the good stuff.</h2>${state.photos.length?`<div class="photo-grid">${state.photos.slice().reverse().map((p,i)=>`<div class="photo-tile tile-${i%4}"><span>${p.label}</span><small>${p.time}</small></div>`).join('')}</div>`:`<div class="empty-photos"><div>✿</div><b>Your memories live here.</b><p>Open Camera and tap the shutter to capture a little moment.</p><button class="primary-action" data-action="open-camera">Open Camera</button></div>`}`)}
