48: function settingsApp(){return shell(2,'Settings',`<div class="settings-profile"><div class="profile-avatar">D</div><div><b>Your Duo</b><p>Both phones, one team.</p></div></div><div class="app-kicker">PERSONALIZE</div><button class="setting-row" data-action="toggle-wallpaper"><span>🎨</span><span><b>Shared wallpaper</b><small>Let the phones match</small></span><i>${state.wallpaper?'ON':'OFF'}</i></button><button class="setting-row" data-action="toggle-dark"><span>🌙</span><span><b>Night mode</b><small>Make it a little cozier</small></span><i>${state.dark?'ON':'OFF'}</i></button><div class="app-kicker">ABOUT YOUR DUO</div><div class="soft-card about-card">DUO OS <span>Version 1.0 · Two is better than one.</span></div>`)}
