70:  if(name.startsWith('reminder-')){const i=Number(name.split('-')[1]);state.reminders[i].done=!state.reminders[i].done;if(state.reminders[i].done)complete('reminder');renderHomes();return}
71:  if(name==='toggle-wallpaper'){state.wallpaper=!state.wallpaper;document.querySelectorAll('.phone-screen').forEach(e=>e.classList.toggle('shared-wallpaper',state.wallpaper));renderHomes();showToast(state.wallpaper?'Your phones are in sync 🎨':'Original wallpapers restored');return}
